std::vector<std::array<double,4>> Fields(const iga::ImmersedActiveLayout& l){std::vector<std::array<double,4>> v(l.NodeIds().size());for(std::size_t i=0;i<v.size();++i)for(int q=0;q<4;++q)v[i][q]=.01*static_cast<double>(static_cast<int>((7*i+q)%11)-5);return v;}
