bool SamePorts(const std::vector<ImmersedTransientFlowDiagnostics::Port>&a,const std::vector<ImmersedTransientFlowDiagnostics::Port>&b){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(!SamePort(a[i],b[i]))return false;return true;}
