struct Snapshot{std::vector<PetscScalar> state;std::string global_hash,geometry,publication,layout_hash;std::vector<std::int32_t>nodes;std::size_t rows;ImmersedTransientFlowDiagnostics diagnostics;std::optional<iga::MovingImmersedTransientFlowConservationDiagnostics> conservation;};
std::optional<iga::MovingImmersedTransientFlowConservationDiagnostics> TryConservation(const MovingImmersedTransientFlowRuntime&r){try{return r.ConservationDiagnostics();}catch(const std::logic_error&){return std::nullopt;}}
Snapshot Take(const MovingImmersedTransientFlowRuntime&r){return{r.CommittedState(),r.CommittedGlobalState().HashSha256(),r.CommittedGeometry().GeometryIdentitySha256(),r.CommittedGeometry().PublicationIdentitySha256(),r.CommittedLayout().HashSha256(),r.CommittedLayout().NodeIds(),r.CommittedLayout().Rows(),r.CommittedDiagnostics(),TryConservation(r)};}
void CheckSnapshot(const MovingImmersedTransientFlowRuntime&r,const Snapshot&b){Check(Bits(r.CommittedState(),b.state),"committed vector changed");Check(r.CommittedGlobalState().HashSha256()==b.global_hash,"committed global state changed");Check(r.CommittedGeometry().GeometryIdentitySha256()==b.geometry&&r.CommittedGeometry().PublicationIdentitySha256()==b.publication,"committed geometry/publication changed");Check(r.CommittedLayout().HashSha256()==b.layout_hash&&r.CommittedLayout().NodeIds()==b.nodes&&r.CommittedLayout().Rows()==b.rows,"committed layout changed");Check(SameInner(r.CommittedDiagnostics(),b.diagnostics),"committed diagnostics or ports changed");if(r.Idle()){const auto conservation=TryConservation(r);Check(conservation.has_value()==b.conservation.has_value()&&(!conservation||SameConservation(*conservation,*b.conservation)),"committed conservation record changed");}}
enum class TransferDirection { Contraction, Expansion };
void CheckTransfer(const MovingImmersedTransientFlowRuntime&r,TransferDirection direction){const auto&old=r.CommittedLayout();const auto&target=r.TrialLayout();const auto old_state=r.CommittedState(),seed=r.TrialState();const auto extension=iga::ImmersedVelocityExtension::Build(r.CommittedGeometry(),old,r.CommittedGlobalState(),r.TrialGeometry(),target,3,{});const auto&history=extension.TargetHistory();Check(old.NodeIds()!=target.NodeIds()&&old.Rows()!=target.Rows(),"strict layout transition did not change node IDs/rows");Check(old.ControllerRow(1)!=target.ControllerRow(1),"stable controller row did not move with layout");Check(target.HasGaugeRow(),"target layout lacks pressure gauge");const double target_gauge=PetscRealPart(seed[target.GaugeRow()]);Check(!std::signbit(target_gauge)&&Bits(target_gauge,0.0),"target seed gauge is not canonical positive zero");Check(history.NodeIds()==target.NodeIds()&&extension.HashSha256()==r.Diagnostics().extension_hash_sha256,"target velocity history does not match the published extension");std::size_t old_only=0,new_only=0,overlap=0;for(auto id:old.NodeIds()){if(!std::binary_search(target.NodeIds().begin(),target.NodeIds().end(),id)){++old_only;continue;}const auto oi=old.LocalNode(id),ti=target.LocalNode(id);++overlap;Check(history.Provenance()[ti]==iga::ImmersedVelocityHistoryProvenance::Committed,"overlapping target node is not committed");for(int q=0;q<4;++q)Check(Bits(seed[4*ti+q],old_state[4*oi+q]),"overlapping velocity or pressure seed lost bitwise anchor value");}for(auto id:target.NodeIds())if(!std::binary_search(old.NodeIds().begin(),old.NodeIds().end(),id)){const auto ti=target.LocalNode(id);++new_only;Check(history.Provenance()[ti]==iga::ImmersedVelocityHistoryProvenance::Extended,"newly activated target node is not extended");}const auto&diagnostics=r.TrialDiagnostics();Check(diagnostics.identity_history_nodes==target.NodeIds().size()&&diagnostics.missing_history_nodes==0&&diagnostics.committed_history_nodes==overlap&&diagnostics.extended_history_nodes==new_only,"history provenance diagnostics do not exactly reconcile with target nodes");if(direction==TransferDirection::Contraction)Check(overlap>0&&old_only>0&&new_only==0&&overlap==target.NodeIds().size(),"nested contraction transfer is not old-only plus target overlap");else Check(overlap>0&&new_only>0&&old_only==0&&overlap==old.NodeIds().size(),"nested expansion transfer is not old overlap plus new-only");Check(Bits(seed[target.ControllerRow(1)],old_state[old.ControllerRow(1)]),"controller continuation was not bitwise by ID");}

struct WallTraceError { double area=0., full=0., tangential=0., normal=0.; };
WallTraceError MeasureWallTraceError(const MovingImmersedTransientFlowRuntime& runtime)
{
	const auto& geometry=runtime.TrialGeometry(); const auto& layout=runtime.TrialLayout(); const auto state=runtime.TrialState();
	WallTraceError result;
	for(std::uint64_t cell=0;cell<geometry.Domain().Cells().size();++cell) {
		if(geometry.Domain().Cells()[cell].classification!=iga::CellClassification::Cut) continue;
		const auto element=geometry.Domain().Background().MaterializeElement(cell);
		const auto& rule=geometry.Surface().UsableRule(geometry.Domain(),cell);
		const auto& provenance=geometry.Surface().UsableProvenance(geometry.Domain(),cell);
		for(std::size_t point=0;point<rule.Points().size();++point) {
			const auto& q=rule.Points()[point]; if(!std::binary_search(runtime.ConfiguredWallLabels().begin(),runtime.ConfiguredWallLabels().end(),q.boundary_id)) continue;
			const auto basis=iga::EvaluateBasis(element,q.parametric[0],q.parametric[1],q.parametric[2],false);
			const auto wall=geometry.Evaluation().WallVelocity(provenance[point].canonical_triangle,provenance[point].canonical_barycentric);
			std::array<double,3> gap{{0.,0.,0.}};
			for(std::size_t a=0;a<element.connectivity.size();++a) for(int i=0;i<3;++i) gap[i]+=(PetscRealPart(state[4*layout.LocalNode(element.connectivity[a])+i])-wall[i])*basis.value[a];
			const double normal=gap[0]*q.normal[0]+gap[1]*q.normal[1]+gap[2]*q.normal[2];
			const double full=gap[0]*gap[0]+gap[1]*gap[1]+gap[2]*gap[2];
			result.area+=q.weight; result.full+=q.weight*full; result.normal+=q.weight*normal*normal; result.tangential+=q.weight*std::max(0.,full-normal*normal);
		}
	}
	Check(result.area>0.&&std::isfinite(result.area),"wall trace fixture has no finite selected area");
	for(double* value:{&result.full,&result.tangential,&result.normal}) {*value=std::sqrt(*value/result.area);Check(std::isfinite(*value),"wall trace error is not finite");}
	return result;
}
